import styled from "styled-components"
import { Search, User, ShoppingCart } from "lucide-react"

export default function Home() {
    return (
        <HomeStyled>
            <NavBar>
                <h1>Juice</h1>
                <ContainerNavigation>
                    <button>Menu</button>
                    <button>About</button>
                    <button>Our specials</button>
                    <button>Our locations</button>
                    <button>Blog</button>
                </ContainerNavigation>
                <ContainerUser>
                    <div><Search /></div>
                    <div><ShoppingCart /></div>
                    <div><User /></div>
                </ContainerUser>
            </NavBar>
            <ContainerContent>
                <ContainerAd>
                    <header>
                        Faster juice delivery service
                    </header>
                    <Title>
                        Juice to make your day Fresh
                    </Title>
                    <Descrição>
                        Stay cool this summer as fruit jucies and Drinks are available online.
                    </Descrição>
                    <Interativos>
                        <Cart><ShoppingCart color="white" /></Cart>
                        <AddToCart>ADD TO CART</AddToCart>
                        <HowItWorks>HOW IT WORKS</HowItWorks>
                    </Interativos>
                </ContainerAd>
                <Image src="https://media.istockphoto.com/id/1400831765/pt/foto/yellow-orange-fruits-and-fresh-orange-juice-squeezing-out-the-fresh-orange.jpg?s=612x612&w=0&k=20&c=yBBz39GihOef42aD__kpNaeXMbkb1rc3Nc64mv_fXU0=" />
            </ContainerContent>
        </HomeStyled>
    )
}

const HomeStyled = styled.main`
position: absolute;
width: 100%;
height: 100%;
`
const NavBar = styled.header`
position: fixed;
width: 100%;
height: 100px;
display: flex;
justify-content: space-around;
align-items: center;
`
const ContainerNavigation = styled.div`
width: 40%;
height: 50px;
display: flex;
align-items: center;
justify-content: space-around;

button {
    background-color:white;
    border: solid 1px white;
    min-width: 70px;
    height: 40px;
    border-top-left-radius: 30px;
    border-bottom-left-radius: 30px;
    border-top-right-radius: 30px;
    border-bottom-right-radius: 30px;
}

button:hover {
    border: solid 1px gray;
    transform: scale(1.05);
}
`
const ContainerUser = styled.div`
width: 10%;
height: 50px;
display: flex;
align-items: center;
justify-content:space-around ;

div {
    width: 40px;
    height: 40px;
    border: 1px solid black;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}
`
const ContainerContent = styled.div`
padding-top: 100px;
background-color: aqua;
width: 100%;
height: 70%;
display: flex;
`
const ContainerAd = styled.div`
background-color: brown;
padding-top: 2%;
width: 40%;
height: 80%;
margin-left: 150px;
display: flex;
flex-direction: column;
justify-content: space-around;

header {
    width: 35%;
    height: 35px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-top-left-radius: 30px;
    border-bottom-left-radius: 30px;
    border-top-right-radius: 30px;
    border-bottom-right-radius: 30px;
    background-color: beige;
    font-size: 20px;
}
`
const Title = styled.span`
font-size: 90px;
`
const Descrição = styled.span`
font-size: 20px;
color: gray;
`
const Interativos = styled.div`
width: 100%;
height: 50px;
display: flex;
align-items: center;
gap: 20px;
`
const AddToCart = styled.button`
color: white;
border: none;
background-color: orange;
width: 30%;
height: 50px;
border-top-left-radius: 30px;
border-bottom-left-radius: 30px;
border-top-right-radius: 30px;
border-bottom-right-radius: 30px;
`
const HowItWorks = styled.button`
border-color: orange;
color: orange;
width: 30%;
height: 50px;
border-top-left-radius: 30px;
border-bottom-left-radius: 30px;
border-top-right-radius: 30px;
border-bottom-right-radius: 30px;
`
const Cart = styled.div`
width: 50px;
height: 50px;
display: flex;
align-items: center;
justify-content: center;
border-radius: 50%;
background-color: orange;
`
const Image = styled.div`
width:40%;
height:60%;
background-color: azure;
`
